function setTracker(){const f=document.querySelector('[data-tracker]');if(!f)return;f.addEventListener('submit',e=>{e.preventDefault();const id=f.querySelector('input').value.trim();document.querySelector('#tracking-result').textContent=id?'No live carrier data is connected to this independent preview for '+id+'. Check the current status in your purchase account or carrier record.':'Enter a tracking ID to check its current record.'})}document.addEventListener('DOMContentLoaded',setTracker);
